INSERT INTO competency_dictionary (id,competency_code,competency_name,competency_name_en,definition,key_behaviors,category,level_descriptions,source,created_at) VALUES (1,'LEADERSHIP_001','战略思维','Strategic Thinking','能够从全局和长远角度思考问题，制定清晰的战略方向，并将战略转化为可执行的行动计划','["能够分析行业趋势和市场变化","制定中长期发展规划和目标","将战略目标分解为具体行动计划","平衡短期目标和长期发展","在复杂环境中做出战略性决策"]','领导力','{"1":"主要关注日常工作，缺乏战略视角","2":"能够理解战略方向，但缺乏制定能力","3":"能够参与战略讨论，提出建设性意见","4":"能够独立制定领域战略，考虑长远发展","5":"具有卓越的战略思维，能够引领组织变革"}','DDI','2026-06-30 06:52:50');
INSERT INTO competency_dictionary (id,competency_code,competency_name,competency_name_en,definition,key_behaviors,category,level_descriptions,source,created_at) VALUES (2,'LEADERSHIP_002','决策能力','Decision Making','在不确定和复杂情况下，能够收集关键信息，分析利弊，及时做出高质量决策','["能够快速识别关键问题和决策点","收集并分析相关信息","评估风险和机会","在压力下保持冷静并做出决策","为决策结果负责"]','领导力','{"1":"决策犹豫不决，依赖他人","2":"能够在明确情况下做出决策","3":"能够在复杂情况下做出合理决策","4":"善于在不确定情况下做出高质量决策","5":"具有卓越的决策直觉，能够在危机中果断决策"}','KornFerry','2026-06-30 06:52:50');
INSERT INTO competency_dictionary (id,competency_code,competency_name,competency_name_en,definition,key_behaviors,category,level_descriptions,source,created_at) VALUES (3,'LEADERSHIP_003','影响力','Influence','能够通过说服、协商和利益整合等方式，影响他人接受自己的想法和方案','["清晰表达自己的观点和主张","理解他人的需求和关注点","运用合适的说服策略","建立共识和获得支持","在缺乏权威的情况下影响他人"]','领导力','{"1":"难以影响他人，沟通效果不佳","2":"能够在直接下属中产生影响力","3":"能够在同事和合作伙伴中产生影响力","4":"能够在高层和跨部门产生影响力","5":"具有强大的个人影响力，能够影响行业和组织方向"}','DDI','2026-06-30 06:52:50');
INSERT INTO competency_dictionary (id,competency_code,competency_name,competency_name_en,definition,key_behaviors,category,level_descriptions,source,created_at) VALUES (4,'LEADERSHIP_004','团队领导力','Team Leadership','能够建立、发展和领导高效团队，激发团队成员潜力，实现团队目标','["明确团队目标和角色分工","选拔和培养合适的人才","建立团队文化和凝聚力","激励和赋能团队成员","处理团队冲突和绩效问题"]','领导力','{"1":"缺乏团队领导经验","2":"能够管理小团队，完成基本任务","3":"能够领导中等规模团队，实现目标","4":"能够建立高绩效团队，培养人才","5":"具有卓越的领导魅力，能够领导大型组织和变革"}','KornFerry','2026-06-30 06:52:50');
INSERT INTO competency_dictionary (id,competency_code,competency_name,competency_name_en,definition,key_behaviors,category,level_descriptions,source,created_at) VALUES (5,'LEADERSHIP_005','变革管理','Change Management','能够推动和实施组织变革，管理变革阻力，确保变革成功','["识别变革需求和机会","制定变革方案和路线图","沟通变革愿景和利益","管理变革阻力和情绪","巩固变革成果"]','领导力','{"1":"不适应变革，抗拒变化","2":"能够适应变革，执行变革方案","3":"能够推动小型变革项目","4":"能够领导中等规模的变革","5":"具有卓越的变革领导力，能够引领组织转型"}','KornFerry','2026-06-30 06:52:50');
INSERT INTO competency_dictionary (id,competency_code,competency_name,competency_name_en,definition,key_behaviors,category,level_descriptions,source,created_at) VALUES (6,'BUSINESS_001','业务洞察','Business Acumen','深刻理解业务模式和商业逻辑，能够识别商业机会和风险','["理解公司商业模式和盈利逻辑","关注市场动态和竞争对手","识别业务增长机会","理解财务数据和业务指标","将工作与业务目标关联"]','业务能力','{"1":"缺乏业务意识，只关注技术","2":"理解基本业务流程","3":"能够理解业务模式和市场","4":"具有敏锐的业务洞察力","5":"具有卓越的商业判断力，能够发现新商机"}','KornFerry','2026-06-30 06:52:50');
INSERT INTO competency_dictionary (id,competency_code,competency_name,competency_name_en,definition,key_behaviors,category,level_descriptions,source,created_at) VALUES (7,'BUSINESS_002','客户导向','Customer Focus','始终关注客户需求和体验，致力于为客户提供价值','["深入理解客户需求和痛点","主动收集客户反馈","将客户需求转化为产品/服务改进","在决策时考虑客户影响","建立长期客户关系"]','业务能力','{"1":"忽视客户需求","2":"能够响应客户基本需求","3":"主动关注客户需求","4":"深入理解客户，提供增值服务","5":"具有卓越的客户洞察，引领客户需求"}','DDI','2026-06-30 06:52:50');
INSERT INTO competency_dictionary (id,competency_code,competency_name,competency_name_en,definition,key_behaviors,category,level_descriptions,source,created_at) VALUES (8,'BUSINESS_003','创新思维','Innovation','能够突破常规思维，提出创新性解决方案，推动持续改进','["挑战现状和传统做法","提出新的想法和解决方案","鼓励团队创新","将创新想法转化为实践","建立创新文化"]','业务能力','{"1":"墨守成规，抵触变化","2":"能够接受新想法","3":"能够提出改进建议","4":"能够推动创新项目","5":"具有卓越的创新能力，能够引领行业创新"}','KornFerry','2026-06-30 06:52:50');
INSERT INTO competency_dictionary (id,competency_code,competency_name,competency_name_en,definition,key_behaviors,category,level_descriptions,source,created_at) VALUES (9,'INTERPERSONAL_001','沟通能力','Communication','能够清晰、准确地表达想法，积极倾听他人，确保信息有效传递','["清晰表达自己的观点和想法","积极倾听他人意见","根据受众调整沟通方式","运用多种沟通渠道和工具","确保信息准确传达和理解"]','人际能力','{"1":"沟通表达不清，理解能力差","2":"能够进行基本沟通","3":"能够清晰表达复杂想法","4":"具有优秀的沟通能力，能够处理冲突","5":"具有卓越的沟通技巧，能够激励和影响他人"}','DDI','2026-06-30 06:52:50');
INSERT INTO competency_dictionary (id,competency_code,competency_name,competency_name_en,definition,key_behaviors,category,level_descriptions,source,created_at) VALUES (10,'INTERPERSONAL_002','人际关系建立','Relationship Building','能够建立和维护广泛的人际网络，发展互利共赢的合作关系','["主动建立人际联系","维护长期合作关系","在组织中建立人脉网络","跨部门协作和建立伙伴关系是","利用人际关系达成目标"]','人际能力','{"1":"人际关系薄弱","2":"能够建立基本工作关系","3":"能够建立较广泛的人际网络","4":"具有强大的人际影响力","5":"具有卓越的人际网络，能够整合资源"}','KornFerry','2026-06-30 06:52:51');
INSERT INTO competency_dictionary (id,competency_code,competency_name,competency_name_en,definition,key_behaviors,category,level_descriptions,source,created_at) VALUES (11,'INTERPERSONAL_003','冲突管理','Conflict Management','能够识别、理解并建设性地处理冲突，将冲突转化为合作机会','["及早识别冲突迹象","理解冲突根源","保持中立和客观","促进建设性对话","找到双赢解决方案"]','人际能力','{"1":"回避冲突或激化矛盾","2":"能够在帮助下处理简单冲突","3":"能够独立处理常见冲突","4":"善于将冲突转化为合作机会","5":"具有卓越的冲突调解能力，能够化解复杂矛盾"}','DDI','2026-06-30 06:52:51');
INSERT INTO competency_dictionary (id,competency_code,competency_name,competency_name_en,definition,key_behaviors,category,level_descriptions,source,created_at) VALUES (12,'THINKING_001','分析思维','Analytical Thinking','能够系统分析问题，识别根本原因，提出逻辑性解决方案','["收集和分析相关信息","识别问题的根本原因","运用逻辑和结构化思维","评估方案的优缺点","基于数据做出判断"]','思维能力','{"1":"缺乏分析能力，凭直觉判断","2":"能够进行基本问题分析","3":"能够运用结构化方法分析问题","4":"具有敏锐的分析洞察力","5":"具有卓越的分析能力，能够解决复杂问题"}','KornFerry','2026-06-30 06:52:51');
INSERT INTO competency_dictionary (id,competency_code,competency_name,competency_name_en,definition,key_behaviors,category,level_descriptions,source,created_at) VALUES (13,'THINKING_002','学习能力','Learning Agility','能够快速学习新知识、新技能，并将其应用于新情境','["保持好奇心和开放心态","快速掌握新知识和技能","将学习应用于实践","从经验中反思和学习","持续自我提升"]','思维能力','{"1":"学习意愿低，难以掌握新技能","2":"能够学习基本新知识","3":"能够快速学习岗位所需技能","4":"具有优秀的学习能力，能够跨界学习","5":"具有卓越的学习敏捷性，能够快速适应变化"}','DDI','2026-06-30 06:52:51');
INSERT INTO competency_dictionary (id,competency_code,competency_name,competency_name_en,definition,key_behaviors,category,level_descriptions,source,created_at) VALUES (14,'THINKING_003','解决问题能力','Problem Solving','能够识别问题，分析根源，制定并实施有效解决方案','["准确识别问题","分析问题的根本原因","生成多个解决方案","选择最佳方案并实施","评估解决效果并改进"]','思维能力','{"1":"缺乏解决问题能力","2":"能够解决简单问题","3":"能够解决常见问题","4":"能够解决复杂问题","5":"具有卓越的问题解决能力，能够处理危机"}','DDI','2026-06-30 06:52:51');
INSERT INTO competency_dictionary (id,competency_code,competency_name,competency_name_en,definition,key_behaviors,category,level_descriptions,source,created_at) VALUES (15,'EXECUTION_001','结果导向','Result Orientation','专注于达成目标和交付结果，在困难情况下也能坚持完成','["设定清晰的目标和标准","监控进度并确保按时完成","在困难情况下坚持目标","追求卓越和持续改进","为结果负责"]','执行力','{"1":"缺乏结果意识，工作拖延","2":"能够完成基本任务","3":"能够达成工作目标","4":"能够超越目标，追求卓越","5":"具有强烈的结果导向，能够带领团队达成挑战性目标"}','KornFerry','2026-06-30 06:52:51');
INSERT INTO competency_dictionary (id,competency_code,competency_name,competency_name_en,definition,key_behaviors,category,level_descriptions,source,created_at) VALUES (16,'EXECUTION_002','项目管理','Project Management','能够有效规划、执行和监控项目，确保项目成功交付','["制定项目计划和里程碑","分配任务和资源","监控项目进度和风险","协调项目相关方","确保项目按时按质完成"]','执行力','{"1":"缺乏项目管理能力","2":"能够参与项目执行","3":"能够管理小型项目","4":"能够管理复杂项目","5":"具有卓越的项目管理能力，能够管理大型项目群"}','DDI','2026-06-30 06:52:51');
INSERT INTO competency_dictionary (id,competency_code,competency_name,competency_name_en,definition,key_behaviors,category,level_descriptions,source,created_at) VALUES (17,'EXECUTION_003','适应能力','Adaptability','能够在变化的环境中保持高效，快速调整自己适应新要求','["积极面对变化和挑战","快速调整工作方式和优先级","在不确定性中保持高效","学习新方法和新工具","帮助他人适应变化"]','执行力','{"1":"抗拒变化，难以适应","2":"能够适应简单变化","3":"能够适应常见变化","4":"能够快速适应复杂变化","5":"具有卓越的适应能力，能够在巨变中引领方向"}','KornFerry','2026-06-30 06:52:51');
